import{_ as r,l,o as a,c,v as t,p as n,x as o,d as p,i,S as s}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"Pratt 算符优先","description":"","frontmatter":{"title":"Pratt 算符优先","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/pratt-parsing.md","filePath":"cs/pratt-parsing.md","lastUpdated":1789023840000}'),P={name:"cs/pratt-parsing.md"};function h(u,e,_,f,m,b){const d=l("Mermaid");return a(),c("div",null,[e[1]||(e[1]=t('<h1 id="pratt-算符优先" tabindex="-1">Pratt 算符优先 <a class="header-anchor" href="#pratt-算符优先" aria-label="Permalink to &quot;Pratt 算符优先&quot;">​</a></h1><div class="epigraph"><p>每个记号一个左约束力与一个 nud/led 函数；解析表达式不必为每一优先级写一层非终结符。</p><footer>—— 据 Pratt, Top Down Operator Precedence, 1973；对照龙书的算符优先与表达式文法整理</footer></div><p>上一课<a href="/cs/peg-packrat">PEG</a>用有序选择能写表达式，但左结合与多层优先级会把规则写成楼梯，左递归还要改。主干 CFG 用分层 <code>E → E + T | T</code>。缺口是<strong>Pratt</strong>：一张算符表，递归下降只留一个 <code>parseExpression(rbp)</code>。本课钉 nud/led 与绑定力，不把整门语言都改成 Pratt。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>LL 分层文法正确但冗长；PEG 长枝优先要小心。Pratt：前缀记号提供 <code>nud</code>（null denotation），中缀/后缀提供 <code>led</code>（left denotation）。当前约束力 <code>lbp</code> 大于调用者的 <code>rbp</code> 则继续吃中缀。缺口是这份<strong>按记号分派的表达式分析</strong>，不是再算 FIRST。</p><p>数字、标识符、<code>(</code> 走 nud；<code>+</code> <code>*</code> <code>.</code> <code>(</code>（调用）走 led。一元 <code>-</code> 与二元 <code>-</code> 用同一 lexeme、不同 nud/led。</p><h3 id="绑定力不是-lalr-的-left" tabindex="-1">绑定力不是 LALR 的 <code>%left</code> <a class="header-anchor" href="#绑定力不是-lalr-的-left" aria-label="Permalink to &quot;绑定力不是 LALR 的 `%left`&quot;">​</a></h3><p><code>%left</code> 改的是冲突格；Pratt 的数字是手写下降的循环条件。二者可对齐同一张优先级表，算法不是同一份自动机。</p><p><span class="marginnote">Pratt 1973（POPL）。Vaughan Pratt 的「自上而下算符优先」被后来的 JS 引擎与教材反复实现。龙书另有算符优先分析（自底向上），名称相近、栈不同，本课不混。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>parse(rbp)</code>：读一个记号，调 <code>nud</code> 得左值；当下一记号 <code>lbp &gt; rbp</code> 则调其 <code>led(左值)</code>。右结合：<code>led</code> 里用 <code>lbp-1</code> 递归。调用与下标是 led，左值已是 callee 或数组。</p>',11)),(a(),n(s,null,{default:o(()=>[i(d,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20TOK%5B%22%E8%AE%B0%E5%8F%B7%22%5D%20--%3E%20NUD%5B%22nud%20%E5%89%8D%E7%BC%80%22%5D%0A%20%20NUD%20--%3E%20LOOP%5B%22lbp%20%3E%20rbp%3F%22%5D%0A%20%20LOOP%20--%3E%20LED%5B%22led%20%E4%B8%AD%E7%BC%80%22%5D%0A%20%20LED%20--%3E%20LOOP%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[p(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<p>与 lex 对接：词法仍负责最长匹配；Pratt 只看种别。不要在 Pratt 里解析类型声明的全部括号歧义——那是 C 的声明语法，不是表达式。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>复杂度对表达式结点线性。错误：nud 表空则非法开头。与递归下降的其余语句（<code>if</code>、块）并列：语句用下降，表达式切 Pratt，是常见手写前端。</p><p>PEG 的表达式规则可生成 Pratt，或直接写循环；本课强调人可维护的一张表。二义在 Pratt 里被表消掉：不会同时返回两棵树。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不处理增量，不把声明符（C <code>int (*p)()</code>）硬塞进 Pratt。后课默认：表达式可用算符表下降；语句级错误恢复下一课。下一课：分析失败之后如何跳过、同步。</p><p>龙书的算符优先（Floyd）是另一算法，点名对照即可，不在本课实现。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Pratt：nud/led + 左右约束力，一张表吃表达式。</li><li>右结合用略小的 rbp 递归。</li><li>与 CFG 分层、PEG 楼梯、LALR <code>%left</code> 对齐的是优先级数字，不是同一自动机。</li><li>出处：Pratt, 1973；对照 Aho et al. 算符优先章。</li></ul>',9))])}const A=r(P,[["render",h]]);export{T as __pageData,A as default};
